"use client";
import {useEffect,useRef,useState} from 'react';import {hotelClient,hotelRpc} from '@/lib/pilot';import type {HandoffScope} from '@/lib/cashier-handoff';import {readBankTransit} from '@/lib/cashier-bank-transit';import {bankCloseMoney} from '@/lib/cashier-bank-close';
export function CashierBankTransit({scope,bank}:{scope:HandoffScope;bank:string}){const [end,setEnd]=useState(''),[result,setResult]=useState<ReturnType<typeof readBankTransit>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const lock=useRef(false),alive=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
async function load(){if(lock.current)return;lock.current=true;setBusy(true);setResult(null);setError('');try{if(!end)throw Error('Choose a reporting cutoff date.');const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen reconciliation.');const r=readBankTransit(await hotelRpc('bank_deposits_in_transit',{p_tenant:scope.tenant,p_property:scope.property,p_bank:bank,p_end:end}),scope,bank,end);const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen reconciliation.');if(alive.current)setResult(r)}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load deposits in transit.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
return <section><h3>Deposits in transit</h3><p>Posted deposits less posted settlements, using accounting dates before the cutoff. Unposted deposit declarations are not included.</p><label>Transit cutoff (exclusive)<input type="date" disabled={busy} value={end} onChange={e=>{setEnd(e.target.value);setResult(null)}}/></label><button type="button" disabled={busy} onClick={()=>void load()}>Review deposits in transit</button>{error&&<p role="alert">{error}</p>}{result&&<div><p role="status">Outstanding posted deposits: {bankCloseMoney(result.total)}</p>{result.entries.length?<div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Posting date</th><th>Deposit reference</th><th>Outstanding</th><th>Review</th></tr></thead><tbody>{result.entries.map(e=><tr key={e.deposit_id}><td>{e.posting_date}</td><td>{e.deposit_id}</td><td>{bankCloseMoney(e.outstanding_minor)}</td><td>{e.requires_review?'Investigate correction timing':'Awaiting ledger settlement'}</td></tr>)}</tbody></table></div>:<p>No outstanding posted deposits before this cutoff.</p>}</div>}</section>}
